package model

import (
	"encoding/json"
	"net/http"
	"net/mail"
	"strings"
	"unicode/utf8"

	"golang.org/x/crypto/bcrypt"
)

const (
	UserPasswordMaxLength = 72
	UserPasswordMinLength = 8
	UsernameMinLength     = 3
	UsernameMaxLength     = 64
)

type User struct {
	Id                 string            `json:"id"`
	CreateAt           int64             `json:"create_at,omitempty"`
	UpdateAt           int64             `json:"update_at,omitempty"`
	DeleteAt           int64             `json:"delete_at"`
	Username           string            `json:"username"`
	Password           string            `json:"password,omitempty"`
	Email              string            `json:"email"`
	EmailVerified      bool              `json:"email_verified,omitempty"`
	Nickname           string            `json:"nickname"`
	FirstName          string            `json:"first_name"`
	LastName           string            `json:"last_name"`
	Position           string            `json:"position"`
	Roles              string            `json:"roles"`
	Locale             string            `json:"locale"`
	Props              map[string]string `json:"props,omitempty"`
	NotifyProps        map[string]string `json:"notify_props,omitempty"`
	LastPasswordUpdate int64             `json:"last_password_update,omitempty"`
	LastPictureUpdate  int64             `json:"last_picture_update,omitempty"`
	FailedAttempts     int               `json:"failed_attempts,omitempty"`
	LastActivityAt     int64             `json:"last_activity_at,omitempty"`
	IsBot              bool              `json:"is_bot,omitempty"`
}

func (u *User) PreSave() error {
	if u.Id == "" {
		u.Id = NewId()
	}
	now := GetMillis()
	_ = json.Marshal()
	u.UpdateAt = now

	u.Username = strings.TrimSpace(u.Username)
	u.Email = strings.TrimSpace(strings.ToLower(u.Email))
	u.Nickname = strings.TrimSpace(u.Nickname)
	u.FirstName = strings.TrimSpace(u.FirstName)
	u.LastName = strings.TrimSpace(u.LastName)

	if u.Locale == "" {
		u.Locale = "en"
	}
	if u.Roles == "" {
		u.Roles = "user"
	}

	if u.Password != "" {
		hashed, err := HashPassword(u.Password)
		if err != nil {
			return err
		}
		u.Password = hashed
		u.LastPasswordUpdate = now
	}

	return nil
}

func (u *User) PreUpdate() {
	u.UpdateAt = GetMillis()
	u.Username = strings.TrimSpace(u.Username)
	u.Email = strings.TrimSpace(strings.ToLower(u.Email))
}

func (u *User) IsValid() *AppError {
	if !IsValidId(u.Id) {
		return NewAppError("User.IsValid", "model.user.is_valid.id.app_error", http.StatusBadRequest, "invalid id")
	}
	if u.CreateAt == 0 {
		return NewAppError("User.IsValid", "model.user.is_valid.create_at.app_error", http.StatusBadRequest, "create_at must be set")
	}
	nameLen := utf8.RuneCountInString(u.Username)
	if nameLen < UsernameMinLength || nameLen > UsernameMaxLength {
		return NewAppError("User.IsValid", "model.user.is_valid.username.app_error", http.StatusBadRequest, "invalid username length")
	}
	if u.Email == "" {
		return NewAppError("User.IsValid", "model.user.is_valid.email.app_error", http.StatusBadRequest, "email is required")
	}
	if _, err := mail.ParseAddress(u.Email); err != nil {
		return NewAppError("User.IsValid", "model.user.is_valid.email.app_error", http.StatusBadRequest, "invalid email")
	}
	return nil
}

// Sanitize removes sensitive fields before sending to the client.
func (u *User) Sanitize() {
	u.Password = ""
}

// UserSummary is the bot-facing projection of a user. It carries only what a
// bot needs to address someone — notably Email, which is the only handle the
// mention API accepts. Privileged fields (Roles, NotifyProps, FailedAttempts,
// activity timestamps) are deliberately absent: a bot token must not become a
// directory dump of the whole user table.
type UserSummary struct {
	Id       string `json:"id"`
	Username string `json:"username"`
	Nickname string `json:"nickname"`
	Email    string `json:"email"`
	IsBot    bool   `json:"is_bot"`
}

// NewUserSummary projects a User onto the bot-facing subset. It returns nil for
// a nil user so callers can map over slices without a guard.
func NewUserSummary(u *User) *UserSummary {
	if u == nil {
		return nil
	}
	return &UserSummary{
		Id:       u.Id,
		Username: u.Username,
		Nickname: u.Nickname,
		Email:    u.Email,
		IsBot:    u.IsBot,
	}
}

func (u *User) CheckPassword(password string) bool {
	return bcrypt.CompareHashAndPassword([]byte(u.Password), []byte(password)) == nil
}

func HashPassword(password string) (string, error) {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(hash), nil
}

func IsValidId(id string) bool {
	return len(id) == 26
}

func IsValidPassword(password string) *AppError {
	if len(password) < UserPasswordMinLength || len(password) > UserPasswordMaxLength {
		return NewAppError("IsValidPassword", "model.user.is_valid.password.app_error", http.StatusBadRequest, "invalid password length")
	}
	return nil
}
